-- Ajuste expresamente autorizado el 16/10/2026. No toca la BBDD remota.
ALTER TABLE `factor_transaccion_bancaria_origen_cuenta` DROP FOREIGN KEY `FK_ftboc_conexion`;
ALTER TABLE `factor_transaccion_bancaria_sincronizacion` DROP FOREIGN KEY `FK_ftbs_conexion`;
ALTER TABLE `factor_transaccion_bancaria_incidencia` DROP FOREIGN KEY `FK_ftbi_conexion`;
ALTER TABLE `factor_transaccion_bancaria_historial` DROP FOREIGN KEY `FK_ftbh_conexion`;
ALTER TABLE `factor_transaccion_bancaria_conexion` RENAME TO `configuracion_bbdd`;
ALTER TABLE `configuracion_bbdd` CHANGE COLUMN `_idfactortransaccionbancariaconexion` `_idconfiguracionbbdd` INT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'PK interna estable de la configuración de BBDD externa. El renombre conserva sus valores y las referencias de los consumidores; nunca se recibe desde la interfaz.', CHANGE COLUMN `factortransaccionbancariaconexionid` `configuracionbbddid` VARCHAR(50) NOT NULL DEFAULT (uuid()) COMMENT 'UUID público estable de la configuración externa. Se conserva durante el renombre y forma parte del contexto autenticado del secreto existente.';
CREATE TABLE `factor_transaccion_bancaria_fuente` (
  `_idconfiguracionbbdd` INT UNSIGNED NOT NULL COMMENT 'PK y FK de la configuración externa usada por el consumidor bancario. Conserva el identificador existente durante el desacoplamiento; una configuración genérica puede existir sin fuente bancaria.',
  `tabla_origen` VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT 'bcp_transaccion_ahorro' COMMENT 'Tabla o vista de origen del contrato bancario. Pertenece exclusivamente al consumidor de transacciones y no a las credenciales reutilizables. Solo admite identificadores simples y lecturas SELECT verificadas por el adaptador bancario.',
  PRIMARY KEY (`_idconfiguracionbbdd`),
  CONSTRAINT `FK_ftbf_configuracion` FOREIGN KEY (`_idconfiguracionbbdd`) REFERENCES `configuracion_bbdd` (`_idconfiguracionbbdd`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Contrato de origen del consumidor bancario separado de la configuración genérica de BBDD. Conserva la tabla de todas las conexiones anteriores, incluidas las que aún no tienen cuentas mapeadas. No contiene credenciales ni resultados de pruebas.';
INSERT INTO `factor_transaccion_bancaria_fuente` (`_idconfiguracionbbdd`, `tabla_origen`) SELECT `_idconfiguracionbbdd`, `tabla_origen` FROM `configuracion_bbdd`;
ALTER TABLE `configuracion_bbdd` DROP COLUMN `tabla_origen`, DROP CONSTRAINT `CK_ftbc_motor`, ADD CONSTRAINT `CK_ftbc_motor` CHECK (`motor` IN ('MYSQL', 'MARIADB')), MODIFY COLUMN `motor` VARCHAR(10) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'MYSQL' COMMENT 'Motor de la BBDD externa. Esta versión soporta MYSQL y MARIADB mediante un adaptador compatible; otros motores requieren implementar su adaptador y validación antes de habilitarlos.', MODIFY COLUMN `host` VARCHAR(253) NOT NULL COMMENT 'Nombre DNS o dirección del servidor externo, sin protocolo, puerto ni credenciales. Guardar no consulta la red; probar o utilizar exige política de destinos autorizados y verificación de identidad TLS.', MODIFY COLUMN `usuario` VARCHAR(128) NOT NULL COMMENT 'Nombre de usuario de autenticación de la BBDD externa. Sus permisos son administrados en el servidor remoto. Cada consumidor aplica sus propias restricciones; la sincronización bancaria exige exclusivamente SELECT y USAGE.', MODIFY COLUMN `habilitado` TINYINT NOT NULL DEFAULT 0 COMMENT 'Disponibilidad administrativa: 1 habilitado y 0 deshabilitado para los consumidores. Puede guardarse sin probar la conexión; no acredita conectividad ni permisos. Deshabilitar conserva credenciales, referencias e historial.', MODIFY COLUMN `base_datos` VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'Nombre de la base externa seleccionada o escrito manualmente por el administrador. La lista obtenida durante la prueba es orientativa; no se exige una prueba exitosa para guardar este valor.', MODIFY COLUMN `clave_version` VARCHAR(50) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Identificador de la clave externa AES de 256 bits. No contiene material de clave. Se resuelve con BBDD_KEYS fuera de esta base; se conservan versiones anteriores para descifrar conexiones existentes.', COMMENT='Configuración reutilizable de acceso a BBDD externas. Credenciales AES-256-GCM con claves externas y TLS verificado. Independiente de tablas y procesos bancarios. Guardar no realiza conexiones remotas; los diagnósticos y tiempos nunca se almacenan.';
ALTER TABLE `factor_transaccion_bancaria_origen_cuenta` ADD CONSTRAINT `FK_ftboc_conexion` FOREIGN KEY (`_idconexion`) REFERENCES `configuracion_bbdd` (`_idconfiguracionbbdd`) ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE `factor_transaccion_bancaria_sincronizacion` ADD CONSTRAINT `FK_ftbs_conexion` FOREIGN KEY (`_idconexion`) REFERENCES `configuracion_bbdd` (`_idconfiguracionbbdd`) ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE `factor_transaccion_bancaria_incidencia` ADD CONSTRAINT `FK_ftbi_conexion` FOREIGN KEY (`_idconexion`) REFERENCES `configuracion_bbdd` (`_idconfiguracionbbdd`) ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE `factor_transaccion_bancaria_historial` ADD CONSTRAINT `FK_ftbh_conexion` FOREIGN KEY (`_idconexion`) REFERENCES `configuracion_bbdd` (`_idconfiguracionbbdd`) ON DELETE RESTRICT ON UPDATE RESTRICT;
